function leerVault() {
  // El texto lo resuelve el nodo "Extraer el texto", pero ese nodo se queda
  // SOLO con la clave que le pides y tira el resto del json, el nombre del
  // fichero incluido. Hay que ir a buscarlo al nodo de lectura, que saca los
  // items en el mismo orden, y emparejarlos por posicion.
  const leidos = $('Leer el vault').all();
  const ficheros = [];
  $input.all().forEach((item, i) => {
    const j = item.json ?? {};
    if (typeof j.contenido !== 'string' || !j.contenido) return;
    const src = leidos[i] ?? {};
    const nombre = src.json?.fileName ?? src.binary?.data?.fileName;
    if (!nombre) return;
    ficheros.push({ nombre, texto: j.contenido });
  });
  return ficheros;
}

function frontmatter(texto) {
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

// Modo: Run Once for All Items.
// Herramienta "buscar_palabras" del agente. Busca en el vault las notas que
// contienen las palabras tal cual, con la misma puntuacion que "Buscar que
// borrar" de 02b.
//
// Existe porque la busqueda por significado falla justo con lo que mas se
// pregunta: nombres propios. El embedding de "Elena" a secas no se parece al
// de una nota que dice "Elena se ha apuntado a escalada", y Qdrant devuelve
// cualquier cosa. Aqui, si la nota dice Elena, sale.

const MAX_RESULTADOS = 8;
const FRAGMENTO = 500;

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

// El nodo de herramienta del agente manda la busqueda en "query". Por si una
// version de n8n la llama de otra forma, vale el primer texto que venga.
const entrada = $('Pregunta del agente').first().json ?? {};
const busqueda = String(entrada.query ??
  Object.values(entrada).find((v) => typeof v === 'string') ?? '').trim();

// Sin acentos, sin signos y en minusculas, para que "revisión" y "revision"
// sean la misma palabra.
const normalizar = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Palabras que salen en cualquier frase y no distinguen una nota de otra. Mas
// corta que la de borrar: aqui "cita" o "nota" pueden ser justo lo buscado.
const VACIAS = new Set(['el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas',
  'de', 'del', 'al', 'en', 'que', 'lo', 'mi', 'me', 'se', 'con', 'para', 'por',
  'es', 'este', 'esta', 'esto', 'eso', 'esa', 'sobre', 'algo']);

const claves = [...new Set(normalizar(busqueda).split(' ')
  .filter((p) => p.length > 2 && !VACIAS.has(p)))];

if (!claves.length) {
  return [{ json: { response: 'Dame una a tres palabras clave, por ejemplo un nombre: "' +
    busqueda + '" no trae ninguna que sirva para buscar.' } }];
}

// El cuerpo sin frontmatter ni la transcripcion cruda, que repite lo mismo con
// mas ruido.
const cuerpo = (texto) => texto
  .replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, '')
  .split('<!-- transcripción cruda -->')[0]
  .replace(/<!--[\s\S]*?-->/g, '')
  .trim();

// Un trozo alrededor de la primera coincidencia, para que el modelo vea el
// contexto del nombre y no solo el principio de la nota.
function fragmento(texto) {
  if (texto.length <= FRAGMENTO) return texto;
  const plano = normalizar(texto);
  let pos = -1;
  for (const c of claves) {
    const i = plano.indexOf(c);
    if (i !== -1 && (pos === -1 || i < pos)) pos = i;
  }
  // normalizar cambia longitudes solo en los signos, asi que la posicion es
  // aproximada. Para un fragmento vale.
  const desde = Math.max(0, Math.min(pos - FRAGMENTO / 3, texto.length - FRAGMENTO));
  return (desde > 0 ? '…' : '') + texto.slice(desde, desde + FRAGMENTO).trim() +
    (desde + FRAGMENTO < texto.length ? '…' : '');
}

const fecha = (iso) => {
  const d = iso ? DateTime.fromISO(iso, { zone: 'Europe/Madrid' }) : null;
  return d && d.isValid ? d : null;
};
const humana = (d) => DIAS[d.weekday - 1] + ' ' + d.day + ' de ' + MESES[d.month - 1] +
  ' de ' + d.year;

const encontradas = [];

for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  // Una nota cancelada no cuenta para nada, tampoco para buscar.
  if (String(fm.cancelado).trim() === 'true') continue;

  const texto = cuerpo(f.texto);
  const heno = normalizar((fm.titulo ?? '') + ' ' + (fm.tags ?? '') + ' ' + texto);
  const palabras = new Set(heno.split(' '));

  let puntos = 0;
  for (const c of claves) {
    if (palabras.has(c)) puntos += 2;          // la palabra entera
    else if (heno.includes(c)) puntos += 1;    // dentro de otra palabra
  }
  if (!puntos) continue;

  const creado = fecha(fm.creado);
  const cuando = fecha(fm.cuando);
  encontradas.push({
    puntos,
    orden: creado ? creado.toMillis() : 0,
    titulo: fm.titulo || f.nombre.replace(/\.md$/, ''),
    tipo: fm.tipo || 'nota',
    creado,
    cuando,
    fichero: f.nombre,
    texto,
  });
}

// A igualdad de palabras, lo mas reciente primero: lo que se dijo hace un mes
// suele valer mas que lo de hace dos anos.
encontradas.sort((a, b) => (b.puntos - a.puntos) || (b.orden - a.orden));
const elegidas = encontradas.slice(0, MAX_RESULTADOS);

if (!elegidas.length) {
  return [{ json: { response: 'Ninguna nota del vault contiene "' + claves.join(' ') +
    '". Prueba otra forma de escribirlo, o busca por tema con buscar_notas.' } }];
}

const bloques = elegidas.map((e) => {
  const cabecera = ['- ' + e.titulo + ' (' + e.tipo + ')'];
  if (e.creado) cabecera.push('apuntada el ' + humana(e.creado));
  if (e.cuando) cabecera.push('para el ' + humana(e.cuando) + ' a las ' + e.cuando.toFormat('HH:mm'));
  cabecera.push('fichero ' + e.fichero);
  return cabecera.join(', ') + '\n  ' + fragmento(e.texto).replace(/\n+/g, '\n  ');
});

const total = encontradas.length > elegidas.length
  ? ' (' + encontradas.length + ' en total, van las ' + elegidas.length + ' que mejor encajan)'
  : '';

return [{ json: { response: 'Notas que contienen "' + claves.join(' ') + '"' + total +
  ':\n\n' + bloques.join('\n\n') } }];
